import logging
from warnings import warn
from moler.device import DeviceFactory
from taf.rfrl.utilities.tl_config import load_default_moler_configuration
from taf.rfrl.utilities.utf_lab.ute_utf_lab import UteUtfLab, UtfLabError, UtfLabTimeoutError
from taf.rfrl.utilities.logger import custom_logger as logger


class UteDcap(UteUtfLab):
    def __init__(self, *args, **kwargs):
        self._utf_lab = None
        warn(f'{self.__class__.__name__} is deprecated. Please use UteUtfLab in taf.rfrl.utilities.utf_lab', DeprecationWarning, stacklevel=2)
        super().__init__(*args, **kwargs)

    def start_dcap(self, timeout=5 * 60, wait=True):
        warn('start_dcap method is deprecated. Please use UteUtfLab in taf.rfrl.utilities.utf_lab', DeprecationWarning, stacklevel=2)
        self._utf_lab = UteDcap._check_if_ute_lab_available() if self._utf_lab is None else self._utf_lab
        if self._utf_lab:
            UteUtfLab.start_utf_lab(timeout=timeout, wait=wait)
        else:
            load_default_moler_configuration()
            test_pc = DeviceFactory.get_device(name='TEST_PC')
            start_cmd = test_pc.get_cmd(cmd_name='dcap_basic_controller',
                                        cmd_params={'operation': 'start', 'wait': wait})
            start_cmd(timeout=timeout)

    def stop_dcap(self, timeout=2 * 60):
        warn('stop_dcap method is deprecated. Please use UteUtfLab in taf.rfrl.utilities.utf_lab', DeprecationWarning, stacklevel=2)
        self._utf_lab = UteDcap._check_if_ute_lab_available() if self._utf_lab is None else self._utf_lab
        if self._utf_lab:
            UteUtfLab.stop_utf_lab(timeout=timeout)
        else:
            test_pc = DeviceFactory.get_device(name='TEST_PC')
            stop_cmd = test_pc.get_cmd(cmd_name='dcap_basic_controller',
                                       cmd_params={'operation': 'stop'})
            stop_cmd(timeout=timeout)

    @staticmethod
    def _extract_logfile(file_path, log_name):
        warn('_extract_logfile method is deprecated. Please use UteUtfLab in taf.rfrl.utilities.utf_lab', DeprecationWarning, stacklevel=2)
        return UteUtfLab._extract_logfile(file_path, log_name)

    @staticmethod
    def _gather_dcap_tracing_logs(path):
        warn('_gather_dcap_tracing_logs method is deprecated. Please use UteUtfLab in taf.rfrl.utilities.utf_lab', DeprecationWarning, stacklevel=2)
        UteUtfLab._gather_utf_lab_tracing_logs(path)

    def check_dcap_udaptes(self, timeout=2 * 60):
        warn('check_dcap_udaptes method is deprecated. Please use UteUtfLab in taf.rfrl.utilities.utf_lab', DeprecationWarning, stacklevel=2)
        self._utf_lab = UteDcap._check_if_ute_lab_available() if self._utf_lab is None else self._utf_lab
        if self._utf_lab:
            return UteUtfLab.check_utf_lab_updates(timeout=timeout)
        else:
            load_default_moler_configuration()
            test_pc = DeviceFactory.get_device(name='TEST_PC')
            # update DCAP URL
            sed_cmd = test_pc.get_cmd(cmd_name='sed',
                                      cmd_params={
                                          'options': "-i 's/dcap-lite-binaries-local/tts-binaries-releases-local/g'",
                                          'input_files': ['/sharedvolume/check_updates.sh']})
            test_pc.get_cmd(cmd_name='sudo', cmd_params={'cmd_object': sed_cmd})()

            dcap_updates_cmd = test_pc.get_cmd(cmd_name='dcap_basic_updates')
            result = dcap_updates_cmd(timeout=timeout)
            return result['UPDATE_AVAILABLE'], result['INSTALLER'], result['LATEST_VERSION']

    def update_dcap(self, timeout=30 * 60):
        warn('update_dcap method is deprecated. Please use UteUtfLab in taf.rfrl.utilities.utf_lab', DeprecationWarning, stacklevel=2)
        self._utf_lab = UteDcap._check_if_ute_lab_available() if self._utf_lab is None else self._utf_lab
        if self._utf_lab:
            UteUtfLab.update_utf_lab(timeout=timeout)
        else:
            update_available, installer_path, latest_version = self.check_dcap_udaptes()

            if update_available:
                load_default_moler_configuration()
                test_pc = DeviceFactory.get_device(name='TEST_PC')
                ip_cmd = test_pc.get_cmd(cmd_name='ip_addr',
                                         cmd_params={'options': 'show eth0'})
                ip_cmd_result = ip_cmd()
                install_sh = 'sudo UTE_CLOUD=1 bash {} {}'.format(installer_path, ip_cmd_result['eth0']['IPV4'][0]['IP'])
                success_line = 'SUCCESS: DCAP Basic {} installed'.format(latest_version)
                install_cmd = test_pc.get_cmd(cmd_name='run_script',
                                              cmd_params={'script_command': install_sh,
                                                          'success_regex': success_line})
                install_cmd(timeout=timeout)
                logger.log_info_to_console(success_line)
            else:
                logger.log_info_to_console('Latest released DCAP version {} already installed'.format(latest_version))

    @staticmethod
    def _get_trace_id(trace_id_obj):
        warn('_get_trace_id method is deprecated. Please use UteUtfLab in taf.rfrl.utilities.utf_lab', DeprecationWarning, stacklevel=2)
        UteUtfLab._get_trace_id(trace_id_obj)

    @staticmethod
    def _check_if_ute_lab_available():
        load_default_moler_configuration()
        test_pc = DeviceFactory.get_device(name='TEST_PC')
        check_cmd = test_pc.get_cmd(cmd_name='which',
                                    cmd_params={'names': ['utf_lab-controller']})
        results = check_cmd()
        if results['utf_lab-controller']:
            return True
        return False


class DcapError(UtfLabError):
    """Exception raised in case of DCAP error"""
    pass


class DcapTimeoutError(UtfLabTimeoutError):
    """Exception raised in case of Timeout on DCAP procedure"""
    pass


message = '''
================ dcap.ute_dcap IS DEPRECATED! ================
|  Please use taf.rfrl.utilities.utf_lab.ute_utf_lab instead.
================ dcap.ute_dcap IS DEPRECATED! ================
'''

logging.warning(message)
